<?php
namespace Modules\Analytics\Services;
use Core\database\DB;use Modules\System\Services\SiteAdminAccess;use RuntimeException;
class AdminUserAccessService{
 public function index(int$a,array$f):array{$c=$this->context($a);$page=max(1,(int)($f['page']??1));$per=in_array((int)($f['perPage']??20),[10,20,30,50,100],true)?(int)$f['perPage']:20;$w=['u.deleted_at IS NULL'];$b=[];$this->scope($c,$w,$b);if(!empty($f['branchId'])){$bid=(int)$f['branchId'];if($c['type']!=='site'&&!in_array($bid,$c['branches'],true))throw new RuntimeException('شعبه خارج از محدوده دسترسی شما است.');$w[]='(EXISTS(SELECT 1 FROM academy_branch_members m WHERE m.user_id=u.user_id AND m.branch_id=? AND m.deleted_at IS NULL) OR EXISTS(SELECT 1 FROM academy_branches x WHERE x.user_id=u.user_id AND x.branch_id=? AND x.deleted_at IS NULL))';array_push($b,$bid,$bid);}if(!empty($f['status'])){$w[]='u.status=?';$b[]=$f['status'];}if(!empty($f['search'])){$q='%'.trim($f['search']).'%';$w[]="(u.username LIKE ? OR u.email LIKE ? OR u.phone LIKE ? OR EXISTS(SELECT 1 FROM translations t WHERE t.table_name='users' AND t.table_id=u.user_id AND t.field='full_name' AND t.deleted_at IS NULL AND t.value LIKE ?))";array_push($b,$q,$q,$q,$q);}$sql=implode(' AND ',$w);$total=(int)$this->query("SELECT COUNT(DISTINCT u.user_id) FROM users u WHERE $sql",$b,true);$offset=($page-1)*$per;$rows=$this->query("SELECT DISTINCT u.* FROM users u WHERE $sql ORDER BY u.user_id DESC LIMIT $offset,$per",$b);return['users'=>array_map(fn($u)=>$this->user($u,$c,$a),$rows),'roles'=>$this->roles($c),'permissions'=>$this->permissions($c),'branches'=>$this->branchOptions($c),'context'=>['type'=>$c['type']],'total'=>$total,'page'=>$page,'perPage'=>$per];}
 public function save(int$a,int$id,array$d):void{$c=$this->context($a);if($id===1||$id===$a)throw new RuntimeException('مجوزهای حساب مدیریت جاری قابل تغییر نیست.');$w=['u.deleted_at IS NULL','u.user_id=?'];$b=[$id];$this->scope($c,$w,$b);if(!(int)$this->query('SELECT COUNT(*) FROM users u WHERE '.implode(' AND ',$w),$b,true))throw new RuntimeException('کاربر خارج از محدوده مدیریت شما است.');$roles=array_values(array_unique(array_map('intval',(array)($d['roleIds']??[]))));$perms=array_values(array_unique(array_map('intval',(array)($d['permissionIds']??[]))));if(array_diff($roles,array_column($this->roles($c),'id'))||array_diff($perms,array_column($this->permissions($c),'id')))throw new RuntimeException('نقش یا مجوز خارج از دامنه مجاز است.');transaction(function()use($a,$id,$c,$roles,$perms){if($c['type']==='site'){$this->sync('user_roles','user_role_id','user_id','role_id',$id,$roles,$a,true);$this->sync('user_permissions','user_permission_id','user_id','permission_id',$id,$perms,$a,false);return;}$m=$this->member($id,$c);$this->sync('academy_branch_member_roles','member_role_id','member_id','role_id',(int)$m['member_id'],$roles,$a,true);$this->sync('academy_branch_member_permissions','academy_branch_member_permission_id','member_id','permission_id',(int)$m['member_id'],$perms,$a,false);});}
 private function context(int$a):array{$u=DB::table('users')->where('user_id',$a)->whereNull('deleted_at')->first();if(!$u)throw new RuntimeException('کاربر معتبر نیست.');if(SiteAdminAccess::allows($u))return['type'=>'site','academy'=>0,'branches'=>[]];$academy=DB::table('academies')->where('user_id',$a)->whereNull('deleted_at')->first()?:DB::table('academies')->where('created_by',$a)->whereNull('deleted_at')->first();$members=DB::table('academy_branch_members')->where('user_id',$a)->whereNull('deleted_at')->get();if(!$academy)foreach($members as$m)if($this->hasRole((int)$m['member_id'],'academy')){$academy=DB::table('academies')->where('academy_id',(int)$m['academy_id'])->whereNull('deleted_at')->first();break;}if($academy){$ids=array_map(fn($x)=>(int)$x['branch_id'],DB::table('academy_branches')->where('academy_id',(int)$academy['academy_id'])->whereNull('deleted_at')->get());return['type'=>'academy','academy'=>(int)$academy['academy_id'],'branches'=>$ids];}$branch=DB::table('academy_branches')->where('user_id',$a)->whereNull('deleted_at')->first();if(!$branch)foreach($members as$m)if($m['branch_id']&&$this->hasRole((int)$m['member_id'],'branch')){$branch=DB::table('academy_branches')->where('branch_id',(int)$m['branch_id'])->whereNull('deleted_at')->first();break;}if(!$branch)throw new RuntimeException('مجوز مدیریت نقش‌ها و دسترسی‌ها را ندارید.');return['type'=>'branch','academy'=>(int)$branch['academy_id'],'branches'=>[(int)$branch['branch_id']]];}
 private function hasRole(int$mid,string$kind):bool{$pattern=$kind==='academy'?"((LOWER(access_system_roles.name) LIKE '%academy%manager%' OR LOWER(access_system_roles.name) LIKE '%academy%owner%') AND LOWER(access_system_roles.name) NOT LIKE '%branch%')":"(LOWER(access_system_roles.name) LIKE '%branch%manager%' OR LOWER(access_system_roles.name) LIKE '%branch%owner%')";return(bool)DB::table('academy_branch_member_roles')->join('access_system_roles','access_system_roles.role_id','=','academy_branch_member_roles.role_id')->where('academy_branch_member_roles.member_id',$mid)->whereRaw($pattern)->whereNull('academy_branch_member_roles.deleted_at')->whereNull('access_system_roles.deleted_at')->first();}
 private function scope(array$c,array&$w,array&$b):void{if($c['type']==='site')return;if($c['type']==='academy'){$w[]='(EXISTS(SELECT 1 FROM academy_branch_members m WHERE m.user_id=u.user_id AND m.academy_id=? AND m.deleted_at IS NULL) OR EXISTS(SELECT 1 FROM academies a WHERE a.user_id=u.user_id AND a.academy_id=? AND a.deleted_at IS NULL) OR EXISTS(SELECT 1 FROM academy_branches x WHERE x.user_id=u.user_id AND x.academy_id=? AND x.deleted_at IS NULL))';array_push($b,$c['academy'],$c['academy'],$c['academy']);}else{$w[]='(EXISTS(SELECT 1 FROM academy_branch_members m WHERE m.user_id=u.user_id AND m.branch_id=? AND m.deleted_at IS NULL) OR EXISTS(SELECT 1 FROM academy_branches x WHERE x.user_id=u.user_id AND x.branch_id=? AND x.deleted_at IS NULL))';array_push($b,$c['branches'][0],$c['branches'][0]);}}
 private function member(int$uid,array$c):array{foreach(DB::table('academy_branch_members')->where('user_id',$uid)->whereNull('deleted_at')->get()as$m)if($c['type']==='academy'&&(int)$m['academy_id']===$c['academy']||$c['type']==='branch'&&in_array((int)$m['branch_id'],$c['branches'],true))return$m;throw new RuntimeException('این حساب، عضویت قابل مدیریت ندارد.');}
 private function sync(string$t,string$pk,string$owner,string$item,int$oid,array$selected,int$a,bool$main):void{$now=date('Y-m-d H:i:s');$rows=DB::table($t)->where($owner,$oid)->get();foreach($rows as$r){$active=in_array((int)$r[$item],$selected,true);$v=$active?['deleted_at'=>null,'deleted_by'=>null,'updated_at'=>$now,'updated_by'=>$a,'approved_at'=>$now,'approved_by'=>$a]:['deleted_at'=>$now,'deleted_by'=>$a,'updated_at'=>$now,'updated_by'=>$a];if($main&&$active)$v['is_main']=(int)$r[$item]===(int)($selected[0]??0)?1:0;DB::table($t)->where($pk,(int)$r[$pk])->update($v);}$known=array_map(fn($r)=>(int)$r[$item],$rows);foreach(array_diff($selected,$known)as$x){$v=[$owner=>$oid,$item=>$x,'created_at'=>$now,'created_by'=>$a,'updated_at'=>$now,'updated_by'=>$a,'approved_at'=>$now,'approved_by'=>$a];if($main)$v['is_main']=$x===(int)($selected[0]??0)?1:0;DB::table($t)->insert($v);}}
 private function roles(array$c):array{$q=DB::table('access_system_roles')->whereNull('deleted_at');if($c['type']==='academy')$q->whereIn('scope',['academy','branch','self']);elseif($c['type']==='branch')$q->whereIn('scope',['branch','self']);return array_map(fn($r)=>['id'=>(int)$r['role_id'],'name'=>$r['name'],'title'=>$this->title('access_system_roles',(int)$r['role_id'],$r['name']),'color'=>$r['color']?:'#64748b'],$q->orderBy('sort_order')->get());}
 private function permissions(array$c):array{$q=DB::table('access_system_permissions')->whereNull('deleted_at');if($c['type']!=='site'){$q->where('group_name','academy');$q->whereIn('scope',$c['type']==='academy'?['academy','branch','self']:['branch','self']);}return array_map(fn($p)=>['id'=>(int)$p['permission_id'],'name'=>$p['name'],'title'=>$this->title('access_system_permissions',(int)$p['permission_id'],$p['name']),'group'=>$p['group_name']?:'other'],$q->orderBy('name')->get());}
 private function user(array$u,array$c,int$a):array{$id=(int)$u['user_id'];$roles=[];$perms=[];$m=$c['type']==='site'?null:$this->findMember($id,$c);if($c['type']==='site'){$rs=$this->query('SELECT r.*,ur.is_main FROM user_roles ur JOIN access_system_roles r ON r.role_id=ur.role_id WHERE ur.user_id=? AND ur.deleted_at IS NULL AND r.deleted_at IS NULL',[$id]);$ps=$this->query('SELECT p.* FROM user_permissions up JOIN access_system_permissions p ON p.permission_id=up.permission_id WHERE up.user_id=? AND up.deleted_at IS NULL AND p.deleted_at IS NULL',[$id]);}elseif($m){$rs=$this->query('SELECT r.*,mr.is_main FROM academy_branch_member_roles mr JOIN access_system_roles r ON r.role_id=mr.role_id WHERE mr.member_id=? AND mr.deleted_at IS NULL AND r.deleted_at IS NULL',[(int)$m['member_id']]);$ps=$this->query('SELECT p.* FROM academy_branch_member_permissions mp JOIN access_system_permissions p ON p.permission_id=mp.permission_id WHERE mp.member_id=? AND mp.deleted_at IS NULL AND p.deleted_at IS NULL',[(int)$m['member_id']]);}else{$rs=$ps=[];}foreach($rs as$r)$roles[]=['id'=>(int)$r['role_id'],'title'=>$this->title('access_system_roles',(int)$r['role_id'],$r['name']),'color'=>$r['color']?:'#64748b'];foreach($ps as$p)$perms[]=['id'=>(int)$p['permission_id'],'title'=>$this->title('access_system_permissions',(int)$p['permission_id'],$p['name'])];return['id'=>$id,'name'=>$this->title('users',$id,$u['username']?:'کاربر '.$id,'full_name'),'username'=>$u['username'],'email'=>$u['email'],'phone'=>$u['phone'],'type'=>$u['type'],'status'=>$u['status'],'lastLogin'=>$u['last_login_at'],'roles'=>$roles,'permissions'=>$perms,'canEdit'=>$id!==1&&$id!==$a&&($c['type']==='site'||(bool)$m)];}
 private function findMember(int$uid,array$c):?array{foreach(DB::table('academy_branch_members')->where('user_id',$uid)->whereNull('deleted_at')->get()as$m)if($c['type']==='academy'&&(int)$m['academy_id']===$c['academy']||$c['type']==='branch'&&in_array((int)$m['branch_id'],$c['branches'],true))return$m;return null;}
 private function branchOptions(array$c):array{$q=DB::table('academy_branches')->whereNull('deleted_at');if($c['type']==='academy')$q->where('academy_id',$c['academy']);elseif($c['type']==='branch')$q->whereIn('branch_id',$c['branches']);return array_map(fn($x)=>['id'=>(int)$x['branch_id'],'name'=>$this->title('academy_branches',(int)$x['branch_id'],'شعبه '.$x['branch_id'],'name'),'academyName'=>''],$q->get());}
 private function title(string$t,int$id,string$f,string$field='title'):string{$tt=in_array($t,['access_system_roles','access_system_permissions'],true)?'f_translations':'translations';$r=DB::table($tt)->where('table_name',$t)->where('table_id',$id)->where('locale',locale())->where('field',$field)->whereNull('deleted_at')->first();return(string)($r['value']??$f);}private function query(string$s,array$b=[],bool$scalar=false):mixed{$q=db()->prepare($s);$q->execute($b);return$scalar?$q->fetchColumn():$q->fetchAll();}
}
